"""Build separate observed and simulator timelines without joining runs."""
import csv,json,pathlib,sys
repo=pathlib.Path(sys.argv[1]);out=pathlib.Path(sys.argv[2]);out.mkdir(parents=True,exist_ok=False)
diag=repo/'docs/dag_defense/environment/diagnostics';original=diag/'isolated-calibration-first-20261126';instrumented=diag/'isolated-first-instrumented-20261126';sim=diag/'first-token-task-single-20261126'
real=[json.loads(x) for x in (original/'real-router-events.jsonl').read_text().splitlines()];assert len({x['request_id'] for x in real})==1
origin=next(x['timestamp_ns'] for x in real if x['event']=='server_arrival');rows=[]
def add(run,event,kind,raw,relative,note):rows.append({'run':run,'event':event,'clock_or_type':kind,'raw_timestamp_or_s':raw,'relative_s':relative,'meaning':note})
for e in real:add('original_calibration',e['event'],'CLOCK_MONOTONIC ns',e['timestamp_ns'],(e['timestamp_ns']-origin)/1e9,'router host event; response completion is stream forwarding boundary')
a=json.loads((instrumented/'audit.json').read_text());r=a['router'];o=r['arrival_ns'];p=a['producer_first_step'];d=a['consumer_first_step'];h=d['host_intervals']
for name,value,note in [('arrival',r['arrival_ns'],'diagnostic non-stream router host arrival'),('prefill_submit',r['prefill_submit_ns'],'router sends producer request'),('producer_step_start',p['host_start_ns'],'host start; not GPU start'),('producer_send_api_start',p['host_intervals']['send_kv_caches_and_hidden_states'][0],'host call; not NCCL transfer start'),('producer_send_api_return',p['host_intervals']['send_kv_caches_and_hidden_states'][1],'host return; not transfer completion'),('producer_step_after_sync',p['host_after_sync_ns'],'device-wide synchronization completed'),('producer_response_read',r['prefill_done_ns'],'response received by diagnostic router'),('consumer_submit',r['decode_submit_ns'],'router sends consumer request'),('consumer_step_start',d['host_start_ns'],'host start; not GPU start'),('consumer_receive_api_start',h['recv_kv_caches_and_hidden_states'][0],'host call'),('kv_ready_lower_bound',h['kv_ready_bound_ns'][0],'last cache install API start; lower bound for serial batch'),('consumer_receive_api_return',h['recv_kv_caches_and_hidden_states'][1],'host return, not GPU KVReady'),('kv_ready_upper_bound',h['kv_ready_bound_ns'][1],'post-install device sync completed; upper bound'),('consumer_first_step_after_sync',d['host_after_sync_ns'],'includes consumer logits and sampler'),('consumer_last_step_after_sync',a['consumer_subsequent_steps'][-1]['host_after_sync_ns'],'last modeled output step synchronization'),('consumer_response_read',r['decode_done_ns'],'non-stream backend response read'),('router_complete',r['router_complete_ns'],'before diagnostic router sends response')]:add('same_input_instrumented_repeat',name,'CLOCK_MONOTONIC ns',value,(value-o)/1e9,note)
b=json.loads((sim/'audit.json').read_text());trans=next(csv.DictReader((sim/'pd-transfers.csv').open()))
for name,value,note in [('arrival',0,'simulated time origin'),('prefill_complete',float(trans['prefill_completed_at_s']),'modeled producer prefill end'),('transfer_start',float(trans['transfer_started_at_s']),'modeled transfer start'),('kv_ready',b['kv_ready_s'],'modeled transfer completion'),('consumer_first_token_start',b['first_token_start_s'],'diagnostic task, synchronized host interval approximation'),('consumer_first_token_end',b['first_token_end_s'],'diagnostic task completion'),('subsequent_decode_start',b['later_decode_start_s'],'first of 63 later Decode batches'),('request_complete',b['new_e2e_s'],'modeled completion, excludes router stream end')]:add('dag_single_request_candidate',name,'simulation seconds',value,value,note)
with (out/'timeline.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
summary={'status':'incomplete_single_request_alignment','original_server_e2e_s':(next(x['timestamp_ns'] for x in real if x['event']=='server_complete')-origin)/1e9,'diagnostic_input_sha256':a['input_sha256'],'producer_steps':a['producer_model_steps'],'consumer_first_steps':a['consumer_kv_bypass_prompt_steps'],'later_decode_steps':a['consumer_subsequent_decode_steps'],'missing':['Original calibration has no worker or GPU KVReady timestamps','Detailed repeat has inserted synchronization and is non-stream; it is not the original E2E','Transfer start/end GPU events and routing/queue causes for this same request not established','Consumer first-token candidate cost and concurrent scheduling are not validated','Streaming router and simulator completion boundaries differ'],'note':'Rows are separate runs and separate clock origins; do not subtract timestamps across runs.'}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
